@media(forced-colors:active){[data-universe-tool] .uf-pair-depth,[data-universe-tool] .uf-pair-depth .uf-pair-separation,[data-universe-tool] .uf-pair-depth .uf-pair-ranges{background:Canvas;border-color:CanvasText;}[data-universe-tool] .uf-pair-depth summary,[data-universe-tool] .uf-pair-depth summary::before,[data-universe-tool] .uf-pair-depth dt,[data-universe-tool] .uf-pair-depth dd strong,[data-universe-tool] .uf-pair-depth dd span,[data-universe-tool] .uf-pair-depth p{color:CanvasText;}[data-universe-tool] .uf-pair-ranges text{fill:CanvasText;}[data-universe-tool] .uf-pair-range-axis,[data-universe-tool] .uf-pair-range-track,[data-universe-tool] .uf-pair-range-line{stroke:CanvasText;}[data-universe-tool] .uf-pair-range-end{fill:CanvasText;stroke:Canvas;}[data-universe-tool] .uf-pair-depth summary:focus-visible{outline-color:Highlight;}}
